{
  "context": {
    "approved_outline": {
      "index": 1,
      "title": "进水与猜疑",
      "core_goal": "排查广播站无声故障，确认进水原因，建立合作与三声铃约定。",
      "major_beats": [
        "[0-2s] 黄金钩子：刺耳的电火花“啪”声伴随重物砸在铁皮配电箱上的闷响。",
        "[2-7s] 矛盾三要素：周野焦急询问广播为何没声，林岚在狭窄的广播站配电柜前用万用表测短路，表示现在无法播音。",
        "[7-20s] 第一次反转：周野怀疑是有人恶意剪断线缆想冲出去找，林岚叫住他，让他凑近亲自看万用表的蜂鸣档读数，共同核对设备状态，确认是短路而非断路，排除了人为剪线的可能。",
        "[20-80s] 中段推进：林岚表示既然不是剪线，下一步需要顺着线路核对室外节点，递给周野手电筒。两人配合拆开外墙接线盒，发现雨水倒灌和铜绿。周野态度软化，自嘲自己太急躁，林岚解释老街线路老化通病，两人开始共同清理积水。",
        "[80-113s] 升级/二次反转：清理完毕后，林岚表示需要更换防水接头，但零件在仓库，今晚只能做临时绝缘处理。周野提出约定：修好恢复广播后，敲三声铃给街坊报平安，林岚点头答应。",
        "[113-120s] 强钩子：林岚在做临时绝缘时，剥线钳突然卡住，她皱眉发现主线绝缘层也脆化了，沉声说：“主线也得换，今晚弄不完了。”"
      ],
      "ending": "开放式悬念，维修任务升级，三声铃约定悬置。",
      "target_duration_sec": 120
    },
    "scene": "短路疑云",
    "model_mapping_snapshot": {
      "FAST": "qwen/qwen3.6-flash",
      "LONG": "zhipu/glm-5.3",
      "STRONG": "qwen/qwen3.7-max",
      "BALANCED": "qwen/qwen3.7-plus"
    }
  },
  "spoken_lines": [
    {
      "line_id": "ep1-s1-l5",
      "kind": "dialogue",
      "speaker": "repairer",
      "text": "站住。先别急着出去，过来一起核对下设备状态。你看万用表蜂鸣档的读数，阻值接近零。这不是断路，是进水导致的短路。确认了原因，我们再决定下一步怎么排查。",
      "performance_hint": "斩钉截铁，用数据反驳主观臆测。前半句果断制止并邀请核对，后半句陈述事实，末尾引导下一步行动，语气不容置疑。",
      "performer_id": "voice-linlan",
      "sfx_category": null
    }
  ]
}

